// Copies contract ABIs from the Foundry build and live addresses from deployments/ into src/generated/, so the app
// always talks to exactly what is deployed. Run from frontend/ after `forge build` at the repository root:
//
//   npm run sync
//
// The generated files are committed, so the app builds without Foundry (on Vercel, for instance).
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..", "..");
const out = join(here, "..", "src", "generated");

const read = (path) => JSON.parse(readFileSync(join(root, path), "utf8"));
const abi = (file, name = file) => read(`out/${file}.sol/${name}.json`).abi;

const abis = {
  zenithHook: abi("ZenithHook"),
  zenithSettler: abi("ZenithSettler"),
  zenithKeeper: abi("ZenithKeeper"),
  zenithReactive: abi("ZenithReactive"),
  mockErc20: abi("MockERC20"),
  poolSwapTest: abi("PoolSwapTest"),
  poolManager: abi("IPoolManager"),
};

let ts = "// Generated by scripts/sync.mjs from the Foundry build. Do not edit by hand.\n\n";
for (const [name, value] of Object.entries(abis)) {
  ts += `export const ${name}Abi = ${JSON.stringify(value, null, 2)} as const;\n\n`;
}
writeFileSync(join(out, "abis.ts"), ts);

const zenith = read("deployments/1301.json");
const keeper = read("deployments/keeper-1301.json");
const reactive = read("deployments/reactive-5318007.json");
const deployment = {
  unichain: {
    chainId: zenith.chainId,
    deployBlock: zenith.block,
    poolManager: zenith.poolManager,
    hook: zenith.hook,
    settler: zenith.settler,
    keeper: keeper.keeper,
    keeperBlock: keeper.block,
    callbackProxy: keeper.callbackProxy,
    token0: zenith.token0,
    token1: zenith.token1,
    fee: zenith.fee,
    tickSpacing: zenith.tickSpacing,
    swapRouter: "0x9140a78c1A137c7fF1c151EC8231272aF78a99A4",
  },
  lasna: {
    chainId: reactive.chainId,
    reactive: reactive.reactive,
    reactiveBlock: reactive.block,
    cronTopic: reactive.cronTopic,
  },
};
writeFileSync(
  join(out, "deployment.ts"),
  "// Generated by scripts/sync.mjs from deployments/. Do not edit by hand.\n\n" +
    `export const deployment = ${JSON.stringify(deployment, null, 2)} as const;\n`,
);
console.log("wrote src/generated/abis.ts and src/generated/deployment.ts");
